 static void ack(OSC m,boolean agenda)throws Exception{require(m.address.equals("/status")&&m.args.size()>=3&&(n(m.args.get(1))==0||agenda&&n(m.args.get(1))==1)&&n(m.args.get(2))>=0,"Stadium did not confirm operation; check device before retrying");}
