 State parameters(Context c,List<Change> changes)throws Exception{require(!changes.isEmpty()&&changes.size()<=128,"Invalid parameter batch");State before=snapshot();Block block=c.verify(before);Set<String> ids=new HashSet<>();List<Change> ordered=new ArrayList<>();for(Change change:changes){Object wire=change.p.valid(change.value);require(ids.add(change.p.identity())&&same(block.value(change.p),change.expected),"Tone changed elsewhere; refresh before editing");if(!same(change.expected,wire))ordered.add(new Change(change.p,wire,change.expected));}if(ordered.isEmpty())return before;ordered.sort(Comparator.comparingInt(x->x.p.type.equals("f")?1:0));backup(before);for(int i=0;i<ordered.size();i++){if(i%4==0)c.verify(snapshot());identity(before);Change change=ordered.get(i);parameter(c,change.p,change.value);}State after=snapshot();Block actual=c.verify(after);for(Change change:changes)require(same(actual.value(change.p),change.p.valid(change.value)),"Parameter readback did not match; nothing retried or saved");return after;}
 State load(int destination,int expected)throws Exception{State before=snapshot();require(before.id==expected,"Preset changed; select again");backup(before);identity(before);Object r=ref(destination);require(n(get(r,"cid_"))==destination&&n(get(r,"type"))==2,"Preset unavailable");edit("/LoadPresetWithCID",destination);for(int i=0;i<12;i++){State after=snapshot();if(after.id==destination)return after;Thread.sleep(150);}throw new IOException("Preset recall was not confirmed");}
 static boolean blocksEqual(State expected,State actual){if(expected.blocks.size()!=actual.blocks.size())return false;for(Block old:expected.blocks)if(!old.settings(actual.block(old.path,old.pos,old.slot)))return false;return true;}
 State save(int expected)throws Exception{State before=snapshot();require(before.id==expected&&before.writable(),"Save is available for the current User preset; use Save Copy otherwise");backup(before);identity(before);edit("/SavePresetWithCID",expected,-1,-1);for(int i=0;i<8;i++){State after=snapshot();require(after.id==expected&&after.scene==before.scene,"Preset changed before Save confirmation");if(!after.dirty){State saved=new State(origin,product,stored(expected),before.preset,before.scene,false);require(blocksEqual(saved,after)&&deep(get(saved.edit,"cg__","entt","snps"),get(after.edit,"cg__","entt","snps")),"Saved values/scene data not verified");identity(after);return after;}Thread.sleep(250);}throw new IOException("Stadium still reports unsaved changes");}
