  OSC response=exchange("/CreateContent","/status",-2,position,2,MP.encode(map("blck",-1,"colr",0,"dvcp","ALL","flow",-1,"name",name)));require(response.args.size()>=3&&n(response.args.get(1))>0&&n(response.args.get(2))>=0,"New allocation unconfirmed; inspect User library before retrying");int id=n(response.args.get(1));require(id!=before.id&&id!=n(get(before.preset,"rcid")),"Independent allocation required");Object r=ref(id);require(n(get(r,"cid_"))==id&&n(get(r,"ccid"))==-2&&n(get(r,"type"))==2&&n(get(r,"posi"))==position&&s(get(r,"name")).equals(name)&&get(r,"rcid")==null,"Allocated identity mismatch");
